n: 1px 0 0;
  appearance: none;
  border-radius: var(--button-border-radius);
  border: 1px solid transparent;
  -moz-user-focus: normal;

  &:hover {
    background: var(--toolbarbutton-hover-background);
    border-color: var(--toolbarbutton-hover-bordercolor);
    box-shadow: var(--toolbarbutton-hover-boxshadow);
  }

  &:hover:active {
    background: var(--toolbarbutton-active-background);
    border-color: var(--toolbarbutton-active-bordercolor);
    box-shadow: var(--toolbarbutton-active-boxshadow);
    transition-duration: 10ms;
  }

  &:focus-visible {
    outline: 2px solid var(--focus-outline-color);
    outline-offset: -2px;
  }

  & > stack > .toolbarbutton-icon-begin {
    width: 16px;
    height: 16px;
    -moz-context-properties: fill, stroke, fill-opacity;
    fill: color-mix(in srgb, currentColor 20%, transparent);
    stroke: currentColor;
    fill-opacity: var(--toolbarbutton-icon-fill-opacity);
  }

  & > stack > .toolbarbutton-day-text {
    text-align: center;
    margin-inline-start: 0;
    margin-bottom: 0;
    font-size: 7pt;
    font-family: Arial, Helvetica, sans-serif;
    font-weight: bold;
    text-shadow: none;
    background-color: transparent;
  }

  &[hideLabel] > .toolbarbutton-text,
  &[hideLabel] > .toolbarbutton-icon-end {
    display: none;
  }

  & > .toolbarbutton-icon-end {
    -moz-context-properties: stroke;
    stroke: currentColor;
  }

  &[checked="true"] > .toolbarbutton-icon-end {
    transform: scaleY(-1);
  }
}

/* iMIP notification bar */
.calendar-notification-bar {
  background-color: var(--color-blue-10);
  padding: 3px;
}

@media (prefers-color-scheme: dark) {
  .calendar-notification-bar {
    background-color: var(--color-purple-40);
  }
}

@media (prefers-contrast) {
  :root:not([lwtheme]) {
    .calendar-notification-bar {
      background-color: var(--selected-item-color);

      & > *:not(#imip-view-toolbox) {
        color: var(--selected-item-text-color);
      }
    }
  }
}

